styles:
/* The shade and the words are two token colours turned round: dark — a shade of the text colour
   under words in the page's colour, light — a veil of the page's colour under words in the text
   colour. Either reads on any photo, and the dark scheme turns both round together. The block's
   own variables are the knobs a site's theme turns: how thick the shade is, how clear the glass. */
.b-text-tiles {
    --text-tiles-shade: var(--site-color-text);
    --text-tiles-ink: var(--site-color-bg);
    --text-tiles-veil: 72%;
    --text-tiles-glass: 30%;
    --text-tiles-glass-solid: 62%;
    --text-tiles-blur: 14px;
    container-type: inline-size;
    position: relative;
    isolation: isolate;
    overflow: hidden;
    padding-block: var(--site-space-7);
    background: var(--text-tiles-shade);
    color: var(--text-tiles-ink);
}

.b-text-tiles--light {
    --text-tiles-shade: var(--site-color-bg);
    --text-tiles-ink: var(--site-color-text);
    --text-tiles-veil: 78%;
}

/* The gradient is the dark shade drawn from the words' side to the clear photo; its colour is a
   knob of its own, the dark shade by default. */
.b-text-tiles--gradient {
    --text-tiles-fade: var(--text-tiles-shade);
}

/* In the column it is a card of its own: rounded, and apart from the block before and after it. */
.b-text-tiles:not(.site-bleed) {
    margin-block: var(--site-space-5);
    border-radius: var(--site-radius-lg);
}

.b-text-tiles__picture {
    position: absolute;
    inset: 0;
    z-index: -2;
    width: 100%;
    max-width: none;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

/* Even, not a gradient: the words and the tiles stand anywhere on the photo, and the thinnest
   part of a gradient would be under one of them. 72% of the text colour over a white pixel still
   leaves the page's colour at 4.5:1 and more (WCAG AA). */
.b-text-tiles__shade {
    position: absolute;
    inset: 0;
    z-index: -1;
    background: color-mix(in srgb, var(--text-tiles-shade) var(--text-tiles-veil), transparent);
}

.b-text-tiles__inner {
    display: grid;
    gap: var(--site-space-6);
    align-items: center;
    width: 100%;
    max-width: var(--site-container-width);
    margin-inline: auto;
    padding-inline: var(--site-space-5);
}

.b-text-tiles.site-bleed .b-text-tiles__inner {
    padding-inline: var(--site-gutter);
}

.b-text-tiles__words {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--site-space-3);
    min-width: 0;
}

.b-text-tiles__eyebrow {
    margin: 0;
    font-size: var(--site-font-size-6);
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.b-text-tiles__heading {
    max-width: 22em;
    margin: 0;
    color: inherit;
    font-family: var(--site-font-heading);
    font-size: var(--site-font-size-3);
    line-height: 1.15;
    hyphens: auto;
}

.b-text-tiles__text {
    max-width: 40em;
    margin: 0;
    white-space: pre-line;
}

.b-text-tiles__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    margin-top: var(--site-space-2);
    padding: 0 var(--site-space-5);
    border: 1px solid transparent;
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    line-height: 1.2;
    text-align: center;
    text-decoration: none;
    transition: background-color var(--site-duration) var(--site-easing);
}

.b-text-tiles__button:hover {
    background: color-mix(in srgb, var(--site-color-accent) 85%, var(--site-color-text));
}

.b-text-tiles__button:focus-visible {
    outline: 2px solid var(--text-tiles-ink);
    outline-offset: 2px;
}

.b-text-tiles__tiles {
    display: grid;
    gap: var(--text-tiles-tiles-gap, var(--site-space-3));
    margin: 0;
    padding: 0;
    list-style: none;
}

/* Glass: more of the shade behind the tile and the photo blurred through it — never lighter than
   the shade around, so the words of a tile keep the contrast of the words beside it. */
.b-text-tiles__tile {
    display: flex;
    flex-direction: column;
    gap: var(--text-tiles-tile-gap, var(--site-space-2));
    min-width: 0;
    margin: 0;
    padding: var(--text-tiles-tile-padding, var(--site-space-4));
    border: 1px solid color-mix(in srgb, var(--text-tiles-ink) 22%, transparent);
    border-radius: var(--site-radius-lg);
    background: color-mix(in srgb, var(--text-tiles-shade) var(--text-tiles-glass), transparent);
    -webkit-backdrop-filter: blur(var(--text-tiles-blur));
    backdrop-filter: blur(var(--text-tiles-blur));
}

/* Without the blur the photo would show through sharp: a denser tile instead. */
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    .b-text-tiles__tile {
        background: color-mix(in srgb, var(--text-tiles-shade) var(--text-tiles-glass-solid), transparent);
    }
}

.b-text-tiles__tile > * {
    margin: 0;
}

.b-text-tiles__icon {
    display: block;
    width: auto;
    max-width: 100%;
    height: 2.5rem;
    border-radius: 0;
    object-fit: contain;
    object-position: left center;
}

.b-text-tiles__icon--mask {
    width: 2.5rem;
    background: currentColor;
    -webkit-mask: var(--b-text-tiles-icon) left center / contain no-repeat;
    mask: var(--b-text-tiles-icon) left center / contain no-repeat;
}

.b-text-tiles__value {
    font-family: var(--site-font-heading);
    font-size: var(--site-font-size-2);
    font-weight: 700;
    line-height: 1;
    overflow-wrap: anywhere;
}

.b-text-tiles__unit {
    font-size: var(--site-font-size-5);
    font-weight: 600;
}

.b-text-tiles__label {
    font-weight: 600;
    line-height: 1.3;
}

.b-text-tiles__line {
    font-size: var(--site-font-size-6);
    line-height: 1.4;
}

/* Two across from a phone up (a 360px screen gives 20.5rem): four tiles are two rows, three end
   in one across both. A narrower column — a sidebar — keeps one tile a row. */
@container (min-width: 20rem) {
    .b-text-tiles__tiles {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .b-text-tiles--1 .b-text-tiles__tiles {
        grid-template-columns: minmax(0, 1fr);
    }

    .b-text-tiles--3 .b-text-tiles__tile:last-child {
        grid-column: 1 / -1;
    }
}

@container (min-width: 40rem) {
    .b-text-tiles {
        padding-block: var(--site-space-8);
    }

    .b-text-tiles__inner {
        padding-inline: var(--site-space-7);
    }

    .b-text-tiles__heading {
        font-size: var(--site-font-size-2);
    }

    .b-text-tiles__tile {
        padding: var(--text-tiles-tile-padding, var(--site-space-5));
    }
}

/* The words on the left, the tiles in two by two on the right. */
@container (min-width: 56rem) {
    .b-text-tiles--words:not(.b-text-tiles--0) .b-text-tiles__inner {
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
        gap: var(--site-space-7);
    }
}

/* Square tiles (`tile_shape: square`): the column of the tiles is a container of its own, and two
   go side by side only where each is still a square its words fit in — beside the words on a
   wide screen, under them on a tablet. Narrower — a column squeezed beside the words, a phone —
   they stand one under another, as tall as their words. The minimum height of a box with an
   aspect ratio is its content, so a tile with more words grows instead of letting them out; the
   explicit stretch in both axes makes the other tile of its row as tall and keeps the width the
   column's (stretched only in height, a box with a ratio takes its width from that height). */
.b-text-tiles__grid {
    container-type: inline-size;
    min-width: 0;
}

.b-text-tiles--square .b-text-tiles__tiles {
    grid-template-columns: minmax(0, 1fr);
}

.b-text-tiles--square .b-text-tiles__tile {
    justify-content: center;
}

.b-text-tiles--square.b-text-tiles--3 .b-text-tiles__tile:last-child {
    grid-column: auto;
}

@container (min-width: 30rem) {
    .b-text-tiles--square:not(.b-text-tiles--1) .b-text-tiles__tiles {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .b-text-tiles--square:not(.b-text-tiles--1) .b-text-tiles__tile {
        align-self: stretch;
        justify-self: stretch;
        aspect-ratio: 1;
    }
}

/* The gradient where the words stand beside the tiles: the full shade under the words — at the
   middle still the even shade's 72%, the contrast of the words there (WCAG AA) — and the clear
   photo at the far side. Stacked, the words span the width: the even dark shade under them. */
@container (min-width: 56rem) {
    .b-text-tiles--gradient .b-text-tiles__shade {
        background: linear-gradient(
            to right,
            var(--text-tiles-fade) 0%,
            color-mix(in srgb, var(--text-tiles-fade) var(--text-tiles-veil), transparent) 50%,
            transparent 100%
        );
    }

    .b-text-tiles--gradient:dir(rtl) .b-text-tiles__shade {
        background: linear-gradient(
            to left,
            var(--text-tiles-fade) 0%,
            color-mix(in srgb, var(--text-tiles-fade) var(--text-tiles-veil), transparent) 50%,
            transparent 100%
        );
    }

    /* Over the clearer side the glass thickens, so the tiles' words stay readable. */
    .b-text-tiles--gradient .b-text-tiles__tile {
        --text-tiles-glass: 45%;
    }
}

/* The accented words of the heading (==words==) cannot take the accent colour over a photo: they keep the colour and lean instead. */
.b-text-tiles .site-accent {
    color: inherit;
    font-style: italic;
}

/* Sliding over the section above (`overlap`), the edge picture stands over the block's top: the block leaves it uncut, and a frame of its own crops the picture. */
.b-text-tiles[data-webx-overlap] {
    overflow: visible;
}

.b-text-tiles__media {
    position: absolute;
    inset: 0;
    z-index: -1;
    overflow: hidden;
    border-radius: inherit;
}
